import { readFile, writeFile } from 'node:fs/promises';

const root = new URL('../', import.meta.url);
const theme = await readFile(new URL('assets/computer-use/autohand.light-gray.cua-theme', root));
const license = await readFile(new URL('assets/computer-use/LICENSE-CUA.md', root), 'utf8');
await writeFile(new URL('src/generated/computerUseCursorTheme.ts', root), [
  '// Generated by scripts/embed-cursor-theme.mjs; do not edit.',
  `/*!\n${license.trim()}\n*/`,
  `export const COMPUTER_USE_CURSOR_THEME = '${theme.toString('base64')}';`,
  '',
].join('\n'));
